module autograde_mux4to1;
reg [0:3] in; reg [0:1] sel; wire out; reg expected; integer i, passed, failed;
mux4to1_gate dut(out, in, sel);
initial begin
  passed = 0; failed = 0;
  for (i = 0; i < 64; i = i + 1) begin
    in[0]=i[0]; in[1]=i[1]; in[2]=i[2]; in[3]=i[3]; sel[0]=i[4]; sel[1]=i[5];
    if (sel[0]==0 && sel[1]==0) expected = in[0];
    else if (sel[0]==0 && sel[1]==1) expected = in[1];
    else if (sel[0]==1 && sel[1]==0) expected = in[2];
    else expected = in[3];
    #1;
    if (out === expected) begin $display("TEST|MUX4TO1|%0d|PASS", i); passed = passed + 1; end
    else begin $display("TEST|MUX4TO1|%0d|FAIL|sel=%b|in=%b|expected=%b|got=%b", i, sel, in, expected, out); failed = failed + 1; end
  end
  if (failed == 0) $display("RESULT|MUX4TO1|PASS|%0d/64", passed); else $display("RESULT|MUX4TO1|FAIL|%0d/64", passed);
  $finish;
end
endmodule

