      $display("TEST|FADDER|%0d|FAIL|input=%b%b%b|expected=%b%b|got=%b%b", i,x,y,z,expected_c,expected_s,c,s);
      failed = failed + 1;
    end
  end
  if(failed == 0) $display("RESULT|FADDER|PASS|%0d/8", passed);
  else $display("RESULT|FADDER|FAIL|%0d/8", passed);
  $finish;
end
endmodule

