module autograde_addsub;
reg [3:0] A, B; reg M; wire [3:0] S; wire V; reg [3:0] expected_s; reg expected_v; integer passed; integer failed;
ADDSUB dut(S,V,A,B,M);
task check;
  input integer id; input [3:0] testA; input [3:0] testB; input testM;
  begin
    A = testA; B = testB; M = testM;
    expected_s = testA + (testB ^ {4{testM}}) + testM;
    if(testM == 1'b0) expected_v = (~(testA[3] ^ testB[3])) & (expected_s[3] ^ testA[3]);
    else expected_v = (testA[3] ^ testB[3]) & (expected_s[3] ^ testA[3]);
    #1;
    if((S === expected_s) && (V === expected_v)) begin
      $display("TEST|ADDSUB|%0d|PASS",id);
      passed = passed + 1;
    end else begin
      $display("TEST|ADDSUB|%0d|FAIL|A=%b|B=%b|M=%b|expectedS=%b|expectedV=%b|gotS=%b|gotV=%b",id,A,B,M,expected_s,expected_v,S,V);
      failed = failed + 1;
    end
  end
endtask
